import Foundation

/// Reads SwiftGen / R.swift generated files and maps accessor paths (`Asset.Colors.brand`, `image.settingsIcon`)
/// to the raw resource names they wrap. Generated files themselves are not reference sources.
public enum GeneratedAccessorScanner {
    /// File names SwiftGen, R.swift and Xcode use for generated accessors.
    static let generatedFileNames: Set<String> = ["R.generated.swift", "GeneratedAssetSymbols.swift"]

    /// True for a generated accessor file: a known generated file name, or a leading comment block (within
    /// `head`) with a SwiftGen / R.swift header. A hand-written file that merely mentions SwiftGen is not generated.
    public static func isGenerated(head: Data, fileName: String? = nil) -> Bool {
        if let fileName, generatedFileNames.contains(fileName) || fileName.hasSuffix("+Generated.swift") { return true }
        let header = headerComments(String(decoding: head, as: UTF8.self))
        if header.contains(where: { line in
            line.hasPrefix("swiftgen")
                || ["generated using swiftgen", "generated by swiftgen", "generated by r.swift"].contains { line.lowercased().hasPrefix($0) }
        }) { return true }
        return header.contains { $0.hasPrefix("swiftlint:disable all") } && header.contains { $0.contains("SwiftGen") }
    }

    /// Text of the comment lines before the first line of code, comment markers stripped.
    static func headerComments(_ text: String) -> [String] {
        var out: [String] = []
        var inBlock = false
        for raw in text.split(separator: "\n", omittingEmptySubsequences: false) {
            var line = raw.trimmingCharacters(in: .whitespaces)
            if line.isEmpty { continue }
            if inBlock || line.hasPrefix("/*") {
                inBlock = !line.contains("*/")
                line = line.replacingOccurrences(of: "/*", with: "").replacingOccurrences(of: "*/", with: "")
                out.append(line.trimmingCharacters(in: CharacterSet(charactersIn: "* ")))
                continue
            }
            guard line.hasPrefix("//") else { break }
            out.append(line.drop { $0 == "/" }.trimmingCharacters(in: .whitespaces))
        }
        return out
    }

    /// Accessor path -> raw name. Each declaration is registered under its full type path and under
    /// `<enclosing type>.<name>` so uses like `R.image.foo` and `Asset.foo` both resolve. A declaration none of the
    /// known shapes resolves (a custom template: `Image("foo", bundle: .module)`) falls back to the first
    /// non-empty, non-interpolated literal of an `Image` / `UIImage` / `NSImage` / `Color` / `UIColor` / `NSColor` initializer.
    public static func accessors(in tokens: [SwiftToken]) -> [String: String] {
        var map: [String: String] = [:]
        var typeStack: [(name: String, depth: Int)] = []
        var depth = 0
        var pendingType: String?
        var decl: (path: [String], resolved: Bool, fallback: String?)?
        var trStrings = 0
        var labelBefore: String?

        func register(_ path: [String], _ raw: String) {
            map[path.joined(separator: ".")] = map[path.joined(separator: ".")] ?? raw
            if path.count >= 2 {
                let short = path.suffix(2).joined(separator: ".")
                map[short] = map[short] ?? raw
            }
        }
        /// True when `tokens[t]` is the first argument (unlabeled, `decorative:` or `named:`) of an `Image("foo")` /
        /// `UIImage(named: "foo", in: .module, compatibleWith: nil)` style initializer. A custom template's other literals (`L10n.table`, a scene id) name nothing.
        func isImageInitArgument(_ t: Int, label: String?) -> Bool {
            let open = label == nil ? t - 1 : t - 3
            guard label == nil || label == "decorative" || label == "named", open >= 1, tokens[open].isPunct("(") else { return false }
            return ["Image", "UIImage", "NSImage", "Color", "UIColor", "NSColor"].contains(tokens[open - 1].text)
        }
        func finishDeclaration() {
            if let current = decl, !current.resolved, let raw = current.fallback { register(current.path, raw) }
            decl = nil
        }

        for (t, tok) in tokens.enumerated() {
            if tok.kind == .punct {
                switch tok.text {
                case "{":
                    depth += 1
                    if let name = pendingType { typeStack.append((name, depth)); pendingType = nil }
                case "}":
                    if let top = typeStack.last, top.depth == depth { finishDeclaration(); typeStack.removeLast() }
                    depth -= 1
                case ":":
                    labelBefore = t > 0 && tokens[t - 1].isName ? tokens[t - 1].text : nil
                    continue
                default:
                    break
                }
                if tok.text != "(" { labelBefore = nil }
                continue
            }
            if tok.kind == .identifier, ["enum", "struct", "class", "extension"].contains(tok.text),
               t + 1 < tokens.count, tokens[t + 1].kind == .identifier {
                pendingType = tokens[t + 1].text
                continue
            }
            if tok.kind == .identifier, ["let", "var", "func", "case"].contains(tok.text),
               t + 1 < tokens.count, tokens[t + 1].kind == .identifier {
                finishDeclaration()
                decl = (typeStack.map(\.name) + [tokens[t + 1].text], false, nil)
                trStrings = 0
                continue
            }
            if tok.kind == .member, tok.text == "tr" { trStrings = 1 }
            if tok.kind == .string, !tok.interpolated, var current = decl, !current.resolved {
                var raw: String?
                if labelBefore == "name" || labelBefore == "key" { raw = tok.text }
                else if trStrings > 0 {
                    trStrings += 1
                    if trStrings == 3 { raw = tok.text }  // L10n.tr("Table", "key", …)
                }
                else if current.fallback == nil, !tok.text.isEmpty, isImageInitArgument(t, label: labelBefore) {
                    current.fallback = tok.text
                    decl = current
                }
                if let raw {
                    register(current.path, raw)
                    current.resolved = true
                    decl = current
                }
            }
            labelBefore = nil
        }
        finishDeclaration()
        return map
    }
}
